import{z as n,x as o,o as e,c as s,q as A,j as l,D as E,d as r,s as i,S as B}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"训练重放与可复现","description":"","frontmatter":{"title":"训练重放与可复现","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/training-replay.md","filePath":"llm/training-replay.md","lastUpdated":1791063341000}'),p={name:"llm/training-replay.md"};function d(h,a,c,m,_,u){const t=o("Mermaid");return e(),s("div",null,[a[2]||(a[2]=A('<h1 id="训练重放与可复现" tabindex="-1">训练重放与可复现 <a class="header-anchor" href="#训练重放与可复现" aria-label="Permalink to &quot;训练重放与可复现&quot;">​</a></h1><div class="epigraph"><p>同一份配置、同一份数据游标、同一份 RNG，应能把损失尖峰再走一遍；做不到，就分不清是坏卡、非确定 CUDA 还是数据管道偷偷换了样本。</p><footer>—— 据 Pineau 等对机器学习可复现性的要求；对照框架确定性算法与大规模训练日志实践</footer></div><p><a href="/llm/straggler-mitigation">上一课</a>可能换过节点、调过预取。下一次损失尖峰时，需要回答：这是数据里的脏样本、非确定求和，还是硬件。本课不重讲 P99。缺口是训练重放：记录足以把全局 batch 再跑一遍的信息，以及哪些并行原语从一开始就放弃 bit 级相同。弹性事件必须出现在重放说明书里，而不是假装 run 是一条光滑曲线。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>GPU 上的原子加、非确定 reduction、FlashAttention 的变体、异步保存与训练抢流，都会让两次前向差一个 ULP，几天之后差出可见损失。</p><p><span class="marginnote">术语翻译：ULP 是「最后一位上的单位」——浮点数能表示的最小间隔。差一个 ULP 意味着数值只在最末一个比特上不同，单独看无关痛痒；但每步迭代都放大它一点，几万步之后就长成肉眼可见的损失抖动。</span></p><p>完全 bit 级相同在万卡上通常不作为目标。可复现的工程定义应分层：同一检查点、同一微批、同一并行计划下，损失应对拍到规定的容差；跨弹性事件只要求 token 会计正确。缺的是把这层定义写进配方，并保存重放所需的种子与游标。</p>',7)),(e(),l(B,null,{default:E(()=>[i(t,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20L1%5B%22%E7%BA%A7%E5%88%AB%E4%B8%80%EF%BC%9A%E5%BE%AE%E6%89%B9%E9%87%8D%E6%94%BE%3Cbr%2F%3E%E5%90%8C%E6%A3%80%E6%9F%A5%E7%82%B9%20%2B%20%E5%90%8C%E8%AE%A1%E5%88%92%20%2B%20%E7%A1%AE%E5%AE%9A%E6%80%A7%E6%A0%B8%22%5D%20--%3E%20G1%5B%22%E6%89%BF%E8%AF%BA%EF%BC%9A%E6%8D%9F%E5%A4%B1%E5%AF%B9%E5%88%B0%E8%A7%84%E5%AE%9A%E5%AE%B9%E5%B7%AE%22%5D%0A%20%20L2%5B%22%E7%BA%A7%E5%88%AB%E4%BA%8C%EF%BC%9A%E6%95%B4%E6%AD%A5%E5%A4%8D%E8%B7%91%22%5D%20--%3E%20G2%5B%22%E6%89%BF%E8%AF%BA%EF%BC%9A%E7%BB%9F%E8%AE%A1%E5%88%86%E5%B8%83%E4%B8%80%E8%87%B4%22%5D%0A%20%20L3%5B%22%E7%BA%A7%E5%88%AB%E4%B8%89%EF%BC%9A%E8%B7%A8%E5%BC%B9%E6%80%A7%E4%BA%8B%E4%BB%B6%22%5D%20--%3E%20G3%5B%22%E5%8F%AA%E6%89%BF%E8%AF%BA%20token%20%E4%BC%9A%E8%AE%A1%E6%AD%A3%E7%A1%AE%22%5D%0A%20%20BASE%5B%22%E9%87%8D%E6%94%BE%E8%AF%B4%E6%98%8E%E4%B9%A6%E5%86%99%E6%B8%85%E4%B9%B0%E7%9A%84%E6%98%AF%E5%93%AA%E4%B8%80%E7%BA%A7%22%5D%20--%3E%20L1%0A%20%20BASE%20--%3E%20L2%0A%20%20BASE%20--%3E%20L3%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=A('<p>数据管道是最常见的假非确定：多进程解码顺序、gzip 并行、过滤阈值随时间改。去污染指纹库一更新，同一游标会对上不同文档。重放必须冻结指纹库版本。</p><h3 id="rng-有多份" tabindex="-1">RNG 有多份 <a class="header-anchor" href="#rng-有多份" aria-label="Permalink to &quot;RNG 有多份&quot;">​</a></h3><p>Python、NumPy、框架、CUDA、Dropout、路由噪声、数据 shuffle，各有种子。只设一个 <code>seed=42</code> 不够。MoE 路由若用噪声，种子要进检查点。FIM 挖空位置、α 采样的多项分布，同理。</p><p><span class="marginnote">直觉类比：多份 RNG 就像一排各管一摊的骰子——一颗管数据顺序、一颗管 dropout、一颗管专家路由噪声。只报 <code>seed=42</code> 等于只说了其中一颗的点数，其余骰子仍在随机掷，重放自然对不上。</span></p><p><span class="marginnote">确定性算法开关会严重降速。应作为「重放模式」打开，而不是生产默认。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每个全局 step 记录：检查点 id、数据游标、全部 RNG、并行计划、软件版本（含注意力核）。尖峰时：拉起同计划、开确定性算法、只跑该微批或其后 N 步，对比激活范数与损失。若单卡重放正常、多卡失败，查集合通信与落后者。若多卡也失败，查数据解码。</p><p><span class="marginnote">常见误区：尖峰一出就先怀疑学习率或脏数据。正确顺序是先重放——单卡能复现而多卡不能，指向集合通信或慢卡；两边都复现不了，才回头查数据管道与算法本身。跳过重放等于蒙着眼睛换零件。</span></p><p>弹性后在日志打 <code>nondet_event=elastic</code>。审计曲线时分段，不把事件两侧点在同一条「可复现」线上。异步检查点的「latest」指针也要进记录，以免重放加载了后一次损坏点。</p><h3 id="与评测" tabindex="-1">与评测 <a class="header-anchor" href="#与评测" aria-label="Permalink to &quot;与评测&quot;">​</a></h3><p>训练中评测的采样若无种子，曲线不可比。评测集版本与去污染清单版本一并冻结。</p><p><span class="marginnote">对拍 1F1B 与 DualPipe 时，容差要比「两次相同调度」更宽，但仍应排除数量级错误。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>浮点结合律在并行归约上不成立，bit 级相同需要固定归约树。大规模训练选择固定计划 + 记录种子，把不确定性关进声明过的盒子（弹性、非确定核）。重放是把盒子外的变量全部钉死，看盒子内是否仍爆炸——若仍爆炸，才是算法或数据。</p>',14)),(e(),l(B,null,{default:E(()=>[i(t,{id:"mermaid-62",class:"mermaid",graph:"flowchart%20TD%0A%20%20LOG%5B%22step%20%E6%97%A5%E5%BF%97%EF%BC%9A%E6%B8%B8%E6%A0%87%20%2F%20RNG%20%2F%20%E8%AE%A1%E5%88%92%22%5D%20--%3E%20REP%5B%22%E9%87%8D%E6%94%BE%E6%A8%A1%E5%BC%8F%EF%BC%9A%E7%A1%AE%E5%AE%9A%E6%80%A7%E6%A0%B8%22%5D%0A%20%20REP%20--%3E%20CMP%5B%22%E5%AF%B9%E6%AF%94%E6%8D%9F%E5%A4%B1%E4%B8%8E%E6%BF%80%E6%B4%BB%E8%8C%83%E6%95%B0%22%5D%0A%20%20CMP%20--%3E%20DATA%5B%22%E6%95%B0%E6%8D%AE%3F%22%5D%0A%20%20CMP%20--%3E%20COMM%5B%22%E9%80%9A%E4%BF%A1%20%2F%20%E7%A1%AC%E4%BB%B6%3F%22%5D%0A%20%20CMP%20--%3E%20ALG%5B%22%E7%AE%97%E6%B3%95%3F%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=A('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>重放不修复故障率，只缩短诊断。它也不能在换了词表之后对拍旧 run。下一课把「训练中评测」从偶然的 <code>print(loss)</code> 收成有预算、不挡训练、可重放的信号管道，否则早期信号本身成为不可复现的噪声源。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>本课不重讲慢卡治理；只补分层可复现与微批重放。</li><li>生产不追求万卡 bit 级；重放模式才开确定性核。</li><li>冻结数据、指纹、种子、并行计划；弹性单独标注。</li><li>多份 RNG 全部进检查点。</li><li>出处：Pineau et al. 对可复现性的讨论；PyTorch 确定性算法；MegaScale / Llama 3 训练日志实践。</li></ul>',4))])}const P=n(p,[["render",d]]);export{D as __pageData,P as default};
